import { MathUtil } from '../../src/common/math'

describe('Math Functions', () => {
  describe('sqrt', () => {
    // Copied from https://github.com/Aisse-258/bigint-isqrt/blob/master/test/sqrt-test.js
    it('Should return square root of big numbers', { timeout: 30_000 }, () => {
      expect(MathUtil.sqrt(BigInt('0'))).toEqual(BigInt('0'))
      expect(MathUtil.sqrt(BigInt('4'))).toEqual(BigInt('2'))
      expect(MathUtil.sqrt(BigInt('9'))).toEqual(BigInt('3'))
      expect(MathUtil.sqrt(BigInt('24')) + 1n).toEqual(BigInt('5'))
      expect(MathUtil.sqrt(BigInt('2359296'))).toEqual(BigInt('1536'))
      expect(MathUtil.sqrt(BigInt('54866395443885995655625'))).toEqual(BigInt('234235768925'))
      expect(
        MathUtil.sqrt(
          BigInt(
            '82120471531550314555681345949499512621827274120673745141541602816614526075010755373654280259022317599142038423759320355177481886719814621305828811322920076213800348341464996337890625'
          )
        )
      ).toEqual(BigInt('9062034624274524065844376014975805577107171799890766992670739972241112960081909332275390625'))
      expect(
        MathUtil.sqrt(
          BigInt(
            ''
          )
        )
      ).toEqual(
        BigInt(
          ''
        )
      )

      for (let i = 1000n; i < 2000n; i++) {
        for (let j = 1n; j < 200n; j++) {
          expect(MathUtil.sqrt(i ** 2n + j)).toEqual(MathUtil.sqrt(i ** 2n))
          expect(MathUtil.sqrt((i + 72975437934762976n) ** 2n + j)).toEqual(
            MathUtil.sqrt((i + 72975437934762976n) ** 2n)
          )
          expect(MathUtil.sqrt((i + 72975437934762976n) ** 2n - j) + 1n).toEqual(
            MathUtil.sqrt((i + 72975437934762976n) ** 2n)
          )
          if (i ** 2n - j >= 0n) {
            expect(MathUtil.sqrt(i ** 2n - j) + 1n).toEqual(MathUtil.sqrt(i ** 2n))
          }
        }
      }
    })

    it('Should return negative numbers same', () => {
      expect(MathUtil.sqrt(BigInt('-25'))).toEqual(BigInt('-25'))
      expect(MathUtil.sqrt(BigInt('-2359295'))).toEqual(BigInt('-2359295'))
      expect(MathUtil.sqrt(BigInt('-54866395443885995655625'))).toEqual(BigInt('-54866395443885995655625'))
      expect(
        MathUtil.sqrt(
          BigInt(
            '-82120471531550314555681345949499512621827274120673745141541602816614526075010755373654280259022317599142038423759320355177481886719814621305828811322920076213800348341464996337890625'
          )
        )
      ).toEqual(
        BigInt(
          '-82120471531550314555681345949499512621827274120673745141541602816614526075010755373654280259022317599142038423759320355177481886719814621305828811322920076213800348341464996337890625'
        )
      )
    })
  })

  describe('abs', () => {
    it('returns the magnitude of negative, zero and positive values', () => {
      expect(MathUtil.abs(-5n)).toEqual(5n)
      expect(MathUtil.abs(0n)).toEqual(0n)
      expect(MathUtil.abs(5n)).toEqual(5n)
      expect(MathUtil.abs(-(2n ** 255n))).toEqual(2n ** 255n)
    })
  })

  describe('div', () => {
    const floorCases: Array<[bigint, bigint, bigint]> = [
      [10n, 3n, 3n],
      [15n, 4n, 3n],
      [20n, 5n, 4n],
      [10n, 2n, 5n],
      [21n, 7n, 3n],
      [42n, 1n, 42n],
      [0n, 1n, 0n],
      [0n, 5n, 0n],
      [-10n, 3n, -4n],
      [10n, -3n, -4n],
      [-10n, -3n, 3n],
      [-10n, 2n, -5n],
      [10n, -2n, -5n],
      [-10n, -2n, 5n]
    ]

    it('handles floor division across common scenarios', () => {
      for (const [numerator, denominator, expected] of floorCases) {
        expect(MathUtil.divFloor(numerator, denominator)).toBe(expected)
      }
    })

    const ceilCases: Array<[bigint, bigint, bigint]> = [
      [10n, 3n, 4n],
      [-10n, 3n, -3n],
      [10n, -3n, -3n],
      [-10n, -3n, 4n],
      [9n, 3n, 3n],
      [-9n, 3n, -3n]
    ]

    it('handles ceiling division across common scenarios', () => {
      for (const [numerator, denominator, expected] of ceilCases) {
        expect(MathUtil.divCeil(numerator, denominator)).toBe(expected)
      }
    })
  })

  describe('mulDiv', () => {
    it('mulDivFloor floors towards negative infinity', () => {
      const cases: Array<[bigint, bigint, bigint, bigint]> = [
        [10n, 3n, 4n, 7n],
        [-10n, 3n, 4n, -8n],
        [10n, -3n, 4n, -8n],
        [-10n, -3n, 4n, 7n]
      ]

      for (const [a, b, d, expected] of cases) {
        expect(MathUtil.mulDivFloor(a, b, d)).toBe(expected)
      }
    })

    it('mulDivCeil rounds towards positive infinity', () => {
      const cases: Array<[bigint, bigint, bigint, bigint]> = [
        [10n, 3n, 4n, 8n],
        [-10n, 3n, 4n, -7n],
        [10n, -3n, 4n, -7n],
        [-10n, -3n, 4n, 8n]
      ]

      for (const [a, b, d, expected] of cases) {
        expect(MathUtil.mulDivCeil(a, b, d)).toBe(expected)
      }
    })
  })
})
